export const envelope = [25, 54, 25];

export default function build(api) {
  const SEAT_Y = 8;
  const DECK_Y = 18;

  // Resolve palette from world theme with robust fallbacks
  const stonePrimary = api.theme?.stone?.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme?.stone?.accent || "minecraft:cracked_stone_bricks";
  const stoneStairs = api.theme?.stone?.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme?.stone?.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme?.stone?.wall || "minecraft:stone_brick_wall";
  const groundPlinth = api.theme?.ground?.plinth || stonePrimary;
  const groundPave = api.theme?.ground?.pavement || "minecraft:smooth_stone";
  const wallParapet = api.theme?.wall?.parapet || stoneWall;
  const wallWalk = api.theme?.wall?.walk || "minecraft:polished_andesite";

  // Safe setter within envelope bounds
  function set(x, y, z, block) {
    if (x >= 0 && x < 25 && y >= 0 && y < 54 && z >= 0 && z < 25) {
      api.set(Math.floor(x), Math.floor(y), Math.floor(z), block);
    }
  }

  // 3D Bresenham line drawing
  function drawLine(x0, y0, z0, x1, y1, z1, block) {
    const dx = Math.abs(x1 - x0);
    const dy = Math.abs(y1 - y0);
    const dz = Math.abs(z1 - z0);
    const sx = x0 < x1 ? 1 : -1;
    const sy = y0 < y1 ? 1 : -1;
    const sz = z0 < z1 ? 1 : -1;
    const n = Math.max(dx, dy, dz);
    if (n === 0) {
      set(x0, y0, z0, block);
      return;
    }
    let x = x0, y = y0, z = z0;
    let ex = 0, ey = 0, ez = 0;
    for (let i = 0; i <= n; i++) {
      set(Math.round(x), Math.round(y), Math.round(z), block);
      ex += dx;
      ey += dy;
      ez += dz;
      if (ex >= n) { x += sx; ex -= n; }
      if (ey >= n) { y += sy; ey -= n; }
      if (ez >= n) { z += sz; ez -= n; }
    }
  }

  // Determine if column (x, z) belongs to bunker base footprint
  function isBaseFootprint(x, z) {
    if (x >= 7 && x <= 17 && z >= 7 && z <= 17) return true;
    if (x >= 5 && x <= 8 && z >= 5 && z <= 8) return true;
    if (x >= 16 && x <= 19 && z >= 5 && z <= 8) return true;
    if (x >= 5 && x <= 8 && z >= 16 && z <= 19) return true;
    if (x >= 16 && x <= 19 && z >= 16 && z <= 19) return true;
    if (x >= 10 && x <= 14 && z >= 3 && z <= 6) return true;
    if (x >= 11 && x <= 13 && (z === 6 || z === 18 || z === 19)) return true;
    if (z >= 11 && z <= 13 && (x === 5 || x === 6 || x === 18 || x === 19)) return true;
    return false;
  }

  // --- 1. GROUND CONFORMANCE & CRACKED CONCRETE BUNKER BASE ---
  for (let x = 0; x < 25; x++) {
    for (let z = 0; z < 25; z++) {
      if (!isBaseFootprint(x, z)) continue;

      const gh = api.heightAt(x, z);
      const groundY = Math.max(0, Math.min(20, SEAT_Y + gh));

      const isInterior = (x >= 9 && x <= 15 && z >= 9 && z <= 15);
      const isCorridor = (x >= 11 && x <= 13 && z >= 4 && z <= 8);

      // Buttress height profile
      let topY = DECK_Y;
      if (x <= 5 || x >= 19 || z <= 5 || z >= 19) {
        topY = SEAT_Y + 4;
      } else if (x === 6 || x === 18 || z === 6 || z === 18) {
        topY = SEAT_Y + 7;
      }

      if (isInterior) {
        // Subfloor foundation up to seat plane
        for (let y = groundY; y < SEAT_Y; y++) {
          set(x, y, z, groundPlinth);
        }
        set(x, SEAT_Y, z, groundPave);
        // Leave y = SEAT_Y + 1 (9) to 14 EMPTY for compiler fit-out!
        set(x, 15, z, stonePrimary);
        set(x, 16, z, wallWalk);
      } else if (isCorridor) {
        // Entrance passage
        for (let y = groundY; y < SEAT_Y; y++) {
          set(x, y, z, groundPlinth);
        }
        set(x, SEAT_Y, z, groundPave);
        // Roof over corridor
        set(x, SEAT_Y + 4, z, stonePrimary);
      } else {
        // Solid reinforced concrete walls / buttresses
        for (let y = groundY; y <= topY; y++) {
          let b = stonePrimary;
          const r = api.random();
          if (r < 0.28) b = stoneAccent;
          else if (r < 0.42) b = "minecraft:mossy_stone_bricks";
          else if (r < 0.52 && y <= SEAT_Y + 3) b = "minecraft:moss_block";

          set(x, y, z, b);
        }

        // Buttress step-ins
        if (topY < DECK_Y) {
          set(x, topY + 1, z, stoneSlab);
        }
      }
    }
  }

  // Reinforced blast door frame at bunker entrance (z = 6)
  for (let y = SEAT_Y + 1; y <= SEAT_Y + 3; y++) {
    set(10, y, 6, "minecraft:iron_block");
    set(14, y, 6, "minecraft:iron_block");
  }
  set(11, SEAT_Y + 3, 6, "minecraft:iron_block");
  set(12, SEAT_Y + 3, 6, "minecraft:iron_block");
  set(13, SEAT_Y + 3, 6, "minecraft:iron_block");
  set(11, SEAT_Y + 1, 6, "minecraft:iron_bars");
  set(13, SEAT_Y + 1, 6, "minecraft:iron_bars");
  set(11, SEAT_Y + 2, 6, "minecraft:iron_bars");
  set(13, SEAT_Y + 2, 6, "minecraft:iron_bars");

  // Parapet & Mezzanine Walkway on Bunker Roof (y = 17)
  for (let x = 7; x <= 17; x++) {
    for (let z = 7; z <= 17; z++) {
      if (x === 7 || x === 17 || z === 7 || z === 17) {
        set(x, 17, z, wallParapet);
      }
    }
  }
  // Corner observation beacons on the deck
  const deckCorners = [[7, 7], [17, 7], [7, 17], [17, 17]];
  for (const [cx, cz] of deckCorners) {
    set(cx, 17, cz, "minecraft:iron_block");
    set(cx, 18, cz, "minecraft:sea_lantern");
    set(cx, 19, cz, "minecraft:iron_bars");
  }

  // Backup battery bank & transformer on bunker deck
  set(8, 17, 9, "minecraft:iron_block");
  set(8, 17, 10, "minecraft:iron_block");
  set(8, 18, 9, "minecraft:daylight_detector");
  set(8, 18, 10, "minecraft:daylight_detector");

  set(16, 17, 14, "minecraft:iron_block");
  set(16, 17, 15, "minecraft:iron_block");
  set(16, 18, 14, "minecraft:copper_grate");
  set(16, 18, 15, "minecraft:redstone_torch");

  // Creeping apocalyptic foliage
  for (let y = SEAT_Y + 2; y <= 17; y++) {
    if (api.random() < 0.45) set(6, y, 7, "minecraft:oak_leaves[persistent=true]");
    if (api.random() < 0.45) set(18, y, 7, "minecraft:oak_leaves[persistent=true]");
    if (api.random() < 0.45) set(6, y, 17, "minecraft:oak_leaves[persistent=true]");
    if (api.random() < 0.45) set(18, y, 17, "minecraft:oak_leaves[persistent=true]");
  }

  // --- 2. STEEL LATTICE MAST & OUTRIGGER STRUTS (y = 18 to 47) ---
  const mastCols = [[11, 11], [13, 11], [11, 13], [13, 13]];
  for (let y = 17; y <= 47; y++) {
    const isJoint = (y % 4 === 2 || y === 18 || y === 47);
    for (const [mx, mz] of mastCols) {
      if (isJoint) {
        set(mx, y, mz, "minecraft:iron_block");
      } else {
        set(mx, y, mz, "minecraft:polished_basalt");
      }
    }

    // Mast cross-bracing
    if (isJoint) {
      set(12, y, 11, "minecraft:iron_bars");
      set(12, y, 13, "minecraft:iron_bars");
      set(11, y, 12, "minecraft:iron_bars");
      set(13, y, 12, "minecraft:iron_bars");
    } else {
      set(12, y, 11, "minecraft:iron_bars");
      set(12, y, 13, "minecraft:iron_bars");
    }

    // Vertical service cable / ladder core
    set(12, y, 12, "minecraft:ladder[facing=north]");
  }

  // Heavy diagonal outrigger legs from bunker to mast
  drawLine(7, 18, 7, 10, 28, 10, stoneWall);
  drawLine(17, 18, 7, 14, 28, 10, stoneWall);
  drawLine(7, 18, 17, 10, 28, 14, stoneWall);
  drawLine(17, 18, 17, 14, 28, 14, stoneWall);

  // Mid-mast service catwalk platform at y = 28..29
  for (let x = 9; x <= 15; x++) {
    for (let z = 9; z <= 15; z++) {
      if (x >= 11 && x <= 13 && z >= 11 && z <= 13) continue;
      set(x, 28, z, "minecraft:copper_grate");
      if (x === 9 || x === 15 || z === 9 || z === 15) {
        set(x, 29, z, "minecraft:iron_bars");
      }
    }
  }

  // Blinking obstruction warning beacons on catwalk corners
  set(9, 28, 9, "minecraft:redstone_block");
  set(9, 29, 9, "minecraft:redstone_lamp");
  set(15, 28, 15, "minecraft:redstone_block");
  set(15, 29, 15, "minecraft:redstone_lamp");

  // --- 3. PHASED-ARRAY RADAR & SECONDARY UPLINK ---
  // Phased-array rectangular grid on East face (y = 22 to 27)
  for (let y = 22; y <= 27; y++) {
    for (let z = 10; z <= 14; z++) {
      set(14, y, z, "minecraft:iron_bars");
      set(15, y, z, "minecraft:iron_block");
      if (y === 24 && z === 12) {
        set(15, y, z, "minecraft:redstone_block");
        set(16, y, z, "minecraft:redstone_lamp");
      } else if ((y + z) % 2 === 0) {
        set(16, y, z, "minecraft:daylight_detector");
      } else {
        set(16, y, z, "minecraft:smooth_quartz");
      }
    }
  }

  // Secondary small uplink dish on West face (y = 22 to 26)
  drawLine(11, 24, 12, 8, 24, 12, "minecraft:iron_block");
  for (let dy = -1; dy <= 1; dy++) {
    for (let dz = -1; dz <= 1; dz++) {
      if (dy === 0 && dz === 0) {
        set(8, 24, 12, "minecraft:iron_block");
      } else {
        set(8, 24 + dy, 12 + dz, "minecraft:smooth_quartz");
      }
    }
  }
  set(7, 24, 12, "minecraft:lightning_rod[facing=west]");

  // Solar cell cluster wings (y = 20 West, y = 32 East)
  drawLine(11, 20, 12, 6, 20, 12, "minecraft:iron_bars");
  for (let x = 6; x <= 9; x++) {
    for (let z = 11; z <= 13; z++) {
      set(x, 20, z, "minecraft:iron_bars");
      set(x, 21, z, "minecraft:daylight_detector");
    }
  }

  drawLine(13, 32, 12, 18, 32, 12, "minecraft:iron_bars");
  for (let x = 15; x <= 18; x++) {
    for (let z = 11; z <= 13; z++) {
      set(x, 32, z, "minecraft:iron_bars");
      set(x, 33, z, "minecraft:daylight_detector");
    }
  }

  // --- 4. MASSIVE SALVAGED COMMUNICATIONS DISH (y = 30 to 44) ---
  // Dish pivot hub & gantry mount
  const hubX = 12, hubY = 33, hubZ = 13;
  set(10, 31, 13, "minecraft:iron_block");
  set(10, 32, 13, "minecraft:iron_block");
  set(14, 31, 13, "minecraft:iron_block");
  set(14, 32, 13, "minecraft:iron_block");
  set(11, 33, 13, "minecraft:iron_block");
  set(12, 33, 13, "minecraft:iron_block");
  set(13, 33, 13, "minecraft:iron_block");

  // Dish aim direction vector (tilted North-Northwest & upward)
  const nx = -0.32, ny = 0.58, nz = -0.75;
  const nLen = Math.sqrt(nx * nx + ny * ny + nz * nz);
  const unx = nx / nLen, uny = ny / nLen, unz = nz / nLen;

  // Parabolic dish bowl voxelization
  for (let x = 3; x <= 21; x++) {
    for (let y = 29; y <= 44; y++) {
      for (let z = 3; z <= 21; z++) {
        const vx = x - hubX;
        const vy = y - hubY;
        const vz = z - hubZ;
        const dPar = vx * unx + vy * uny + vz * unz;
        const vPerpX = vx - dPar * unx;
        const vPerpY = vy - dPar * uny;
        const vPerpZ = vz - dPar * unz;
        const r = Math.sqrt(vPerpX * vPerpX + vPerpY * vPerpY + vPerpZ * vPerpZ);

        if (r <= 6.8) {
          const targetD = 0.055 * r * r;
          if (Math.abs(dPar - targetD) <= 0.62) {
            let b = "minecraft:smooth_quartz";
            if (r >= 6.0) {
              b = "minecraft:iron_block";
            } else if (r >= 3.8 && r <= 4.4) {
              b = "minecraft:copper_grate";
            } else if (api.random() < 0.12) {
              const rnd = api.random();
              if (rnd < 0.4) b = "minecraft:oxidized_copper";
              else if (rnd < 0.7) b = stoneAccent;
              else b = "minecraft:iron_bars";
            }
            set(x, y, z, b);
          }
        }
      }
    }
  }

  // 8 Structural Ribs behind the dish bowl
  const uBasisX = 0.92, uBasisY = 0, uBasisZ = -0.39;
  const wBasisX = -0.23, wBasisY = -0.82, wBasisZ = -0.53;
  for (let k = 0; k < 8; k++) {
    const theta = (k * Math.PI) / 4;
    const erX = Math.cos(theta) * uBasisX + Math.sin(theta) * wBasisX;
    const erY = Math.cos(theta) * uBasisY + Math.sin(theta) * wBasisY;
    const erZ = Math.cos(theta) * uBasisZ + Math.sin(theta) * wBasisZ;

    const rimX = Math.round(hubX + 2.1 * unx + 6.2 * erX);
    const rimY = Math.round(hubY + 2.1 * uny + 6.2 * erY);
    const rimZ = Math.round(hubZ + 2.1 * unz + 6.2 * erZ);

    drawLine(hubX, hubY, hubZ, rimX, rimY, rimZ, "minecraft:iron_bars");
  }

  // Transceiver Feed Horn at focal point (f = 4.6 blocks along axis)
  const fx = Math.round(hubX + 4.6 * unx); // ~10
  const fy = Math.round(hubY + 4.6 * uny); // ~36
  const fz = Math.round(hubZ + 4.6 * unz); // ~10

  set(fx, fy, fz, "minecraft:sea_lantern");
  set(fx, fy + 1, fz, "minecraft:copper_grate");
  set(fx, fy - 1, fz, "minecraft:copper_grate");
  set(fx + 1, fy, fz, "minecraft:lightning_rod[facing=south]");

  // Tripod support struts connecting rim to receiver
  const tripodAngles = [Math.PI / 2, (7 * Math.PI) / 6, (11 * Math.PI) / 6];
  for (const theta of tripodAngles) {
    const erX = Math.cos(theta) * uBasisX + Math.sin(theta) * wBasisX;
    const erY = Math.cos(theta) * uBasisY + Math.sin(theta) * wBasisY;
    const erZ = Math.cos(theta) * uBasisZ + Math.sin(theta) * wBasisZ;

    const rimX = Math.round(hubX + 2.1 * unx + 6.2 * erX);
    const rimY = Math.round(hubY + 2.1 * uny + 6.2 * erY);
    const rimZ = Math.round(hubZ + 2.1 * unz + 6.2 * erZ);

    drawLine(rimX, rimY, rimZ, fx, fy, fz, "minecraft:iron_bars");
  }

  // --- 5. TOP SPIRE, WARNING BEACONS & HV CONDUITS ---
  // High-voltage snaking cables from dish down mast to bunker
  drawLine(fx, fy, fz, hubX, hubY, hubZ, "minecraft:chain");
  drawLine(hubX, hubY, hubZ, 11, 28, 14, "minecraft:chain");
  drawLine(11, 28, 14, 10, 22, 14, "minecraft:chain");
  drawLine(10, 22, 14, 10, 18, 14, "minecraft:chain");

  // Mast Top Aviation Obstruction Light & Lightning Rod Spire (y = 45 to 49)
  set(12, 45, 12, "minecraft:redstone_block");
  set(12, 46, 12, "minecraft:redstone_lamp");
  set(11, 46, 12, "minecraft:redstone_torch");
  set(13, 46, 12, "minecraft:redstone_torch");
  set(12, 46, 11, "minecraft:redstone_torch");
  set(12, 46, 13, "minecraft:redstone_torch");

  set(12, 47, 12, "minecraft:iron_block");
  set(11, 47, 12, "minecraft:lightning_rod[facing=west]");
  set(13, 47, 12, "minecraft:lightning_rod[facing=east]");
  set(12, 47, 11, "minecraft:lightning_rod[facing=north]");
  set(12, 47, 13, "minecraft:lightning_rod[facing=south]");

  set(12, 48, 12, "minecraft:lightning_rod[facing=up]");
  set(12, 49, 12, "minecraft:lightning_rod[facing=up]");

  return {
    name: "jury_rigged_comm_spire",
    seatY: SEAT_Y,
    anchors: {
      front: [12, SEAT_Y + 1, 0],
      door: [12, SEAT_Y + 1, 4],
      spire: [12, 49, 12],
      dish_hub: [hubX, hubY, hubZ]
    },
    interiors: [
      {
        min: [9, SEAT_Y + 1, 9],
        max: [15, 14, 15],
        kind: "vault"
      }
    ]
  };
}
